import SwiftUI

/// The S1 dashboard: sparse lit pixels, no animations (implicit animations pull
/// the ProMotion panel to high refresh — this is the energy ticket). Content
/// cadence comes from TimelineView's period, driven by the refresh toggle.
///
/// Styling previews `docs/design-language.md` (Soft Instrument) so the direction
/// can be judged on-device ahead of FRO-425; the measurement mechanics — theme /
/// refresh / backend arms, per-tick fractional digits, formatted-once display
/// strings — are unchanged, and the run header carries a `ui` tag so pre- and
/// post-restyle CSVs stay segmentable. Tokens stay file-local: the canonical
/// `Theme.swift` lands in the Rouleur target with 0.3.0, not here.
struct HarnessScreen: View {
    @Bindable var model: HarnessModel
    let workout: WorkoutController
    @State private var showLab: Bool

    init(model: HarnessModel, workout: WorkoutController, openLabAtLaunch: Bool = false) {
        self.model = model
        self.workout = workout
        _showLab = State(initialValue: openLabAtLaunch)
    }

    // MARK: - Design-language tokens (docs/design-language.md), per theme arm.
    // The WHT arm is the FRO-393 measurement comparison, not a product light
    // mode (the ride screen has no light mode by rule) — it inverts the ground
    // but keeps the same component grammar.

    private enum DL {
        static let volt = Color(red: 0.831, green: 1.0, blue: 0.239)      // #D4FF3D
        static let good = Color(red: 0.204, green: 0.816, blue: 0.486)    // #34D07C
        static let raisedDark = Color(red: 0.102, green: 0.114, blue: 0.137)  // #1A1D23
        static let raisedLight = Color(red: 0.937, green: 0.945, blue: 0.957) // invented for the WHT arm — not a decided token
        static let grayMid = Color(red: 0.604, green: 0.631, blue: 0.671)     // #9AA1AB
        static let grayDeep = Color(red: 0.365, green: 0.392, blue: 0.431)    // #5D646E

        // Type roles from the doc; label tracking is +14% of the point size.
        static let hero = Font.system(size: 96, weight: .heavy, design: .rounded)
        static let dataMedium = Font.system(size: 21, weight: .bold, design: .rounded)
        static let unit = Font.system(size: 13, weight: .semibold, design: .rounded)
        static let label = Font.system(size: 11, weight: .medium, design: .monospaced)
        static let labelTracking: CGFloat = 1.5
        static let button = Font.system(size: 17, weight: .heavy, design: .rounded)
    }

    private enum Arc {
        static let size: CGFloat = 180
        static let width: CGFloat = 12
        static let topKmh: Double = 60
    }

    private var isBlack: Bool { model.theme == .black }
    private var background: Color { isBlack ? .black : .white }
    private var ink: Color { isBlack ? .white : .black }
    private var inkSecondary: Color { isBlack ? DL.grayMid : DL.grayDeep }
    private var inkTertiary: Color { isBlack ? DL.grayDeep : DL.grayMid }
    private var raised: Color { isBlack ? DL.raisedDark : DL.raisedLight }

    var body: some View {
        ZStack {
            background.ignoresSafeArea()
            VStack(spacing: 24) {
                statusRow
                // 1:2 spacer split — the instrument sits above optical center.
                // The doubled spacer below is intentional, not a paste error.
                Spacer(minLength: 0)
                dashboard
                Spacer(minLength: 0)
                Spacer(minLength: 0)
                if let error = model.loggerError {
                    Text(error)
                        .font(.footnote.monospaced())
                        .foregroundStyle(.red)
                }
                controls
            }
            .padding(16)
        }
        .persistentSystemOverlays(.hidden)
        // Kill implicit animations globally; readouts must repaint, not animate.
        .transaction { $0.animation = nil }
    }

    // MARK: - Status chips (change at GPS / 5 s cadence, outside the tick train)

    private var statusRow: some View {
        HStack(spacing: 8) {
            chip {
                Circle()
                    .fill(model.hasFix ? DL.good : inkTertiary)
                    .frame(width: 8, height: 8)
                Text(model.hasFix ? "GPS ±\(model.accuracyText) M" : "GPS --")
            }
            chip { Text("THERM \(model.thermalText)") }
            Spacer(minLength: 0)
            // The battery chip is the product's signature element (the wedge
            // made visible) — volt on raised per spec; the WHT arm flips to
            // black-on-volt (light treatment is deliberately undecided).
            chip(accent: true) { Text("BATT \(model.batteryText)%") }
        }
    }

    private func chip(accent: Bool = false, @ViewBuilder content: () -> some View) -> some View {
        HStack(spacing: 6, content: content)
            .font(DL.label)
            .tracking(DL.labelTracking)
            .foregroundStyle(accent ? (isBlack ? DL.volt : .black) : inkSecondary)
            .padding(.horizontal, 12)
            .padding(.vertical, 6)
            .background(accent && !isBlack ? DL.volt : raised, in: .capsule)
    }

    // MARK: - Instrument

    private var dashboard: some View {
        VStack(spacing: 24) {
            hero
            HStack(spacing: 12) {
                metricCard("DISTANCE") { metricValue(model.distanceText, unit: "km") }
                metricCard("RIDE TIME") {
                    // The tick train is scoped to the single readout that needs
                    // it, so both refresh arms diff an identical one-Text tree
                    // and the A/B measures refresh cost, not dashboard-diff
                    // cost. Anchored to the run start, not `.now`: a fresh
                    // anchor per body would re-phase the ticks and add wakeups.
                    TimelineView(.periodic(from: model.startDate ?? .distantPast, by: model.refreshMode.period)) { context in
                        metricValue(elapsedText(now: context.date))
                    }
                }
            }
        }
    }

    /// Central hero with the range arc: where you are in 0–60 km/h, read
    /// before the digits (the Taycan lesson from the design doc).
    private var hero: some View {
        VStack(spacing: 2) {
            rangeArc(fraction: min(model.speedKmh / Arc.topKmh, 1))
            Text(model.speedText)
                .font(DL.hero)
                .monospacedDigit()
                .tracking(-2.9) // −3% of 96 pt per the type spec
                .foregroundStyle(ink)
            Text("KM/H")
                .font(DL.label)
                .tracking(DL.labelTracking)
                .foregroundStyle(inkTertiary)
        }
    }

    private func rangeArc(fraction: Double) -> some View {
        ZStack {
            arcStroke(to: 1, color: raised)
            arcStroke(to: fraction, color: ink)
        }
        .frame(width: Arc.size, height: Arc.size)
        // Only the top semicircle is drawn; pull the empty lower half out of
        // the layout. The overlap point is where the round caps end past the
        // diameter: size/2 + width/2.
        .padding(.bottom, -(Arc.size + Arc.width) / 2)
    }

    /// Circle paths run clockwise from 3 o'clock, so t ∈ [0.5, 1] is the top
    /// semicircle traced left → right — no rotation modifier needed.
    private func arcStroke(to fraction: Double, color: Color) -> some View {
        Circle()
            .trim(from: 0.5, to: 0.5 + fraction * 0.5)
            .stroke(color, style: StrokeStyle(lineWidth: Arc.width, lineCap: .round))
    }

    private func metricCard(_ label: String, @ViewBuilder value: () -> some View) -> some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(label)
                .font(DL.label)
                .tracking(DL.labelTracking)
                .foregroundStyle(inkTertiary)
            value()
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(16)
        .background(raised, in: .rect(cornerRadius: 16))
    }

    private func metricValue(_ text: String, unit: String? = nil) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: 4) {
            Text(text)
                .font(DL.dataMedium)
                .monospacedDigit()
                .foregroundStyle(ink)
            if let unit {
                Text(unit)
                    .font(DL.unit)
                    .foregroundStyle(inkTertiary)
            }
        }
    }

    // MARK: - Lab controls (measurement arms — not product UI)

    private var controls: some View {
        VStack(spacing: 12) {
            HStack(spacing: 12) {
                Picker("Theme", selection: $model.theme) {
                    ForEach(HarnessTheme.allCases) { Text($0.label).tag($0) }
                }
                Picker("Refresh", selection: $model.refreshMode) {
                    ForEach(RefreshMode.allCases) { Text($0.label).tag($0) }
                }
                Picker("GPS", selection: $model.backend) {
                    ForEach(LocationBackend.allCases) { Text($0.label).tag($0) }
                }
            }
            .pickerStyle(.segmented)
            HStack(spacing: 12) {
                Button {
                    model.isRunning ? model.stop() : model.start()
                } label: {
                    Text(model.isRunning ? "STOP" : "START")
                        .font(DL.button)
                        .tracking(1)
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(CapsuleButtonStyle(fill: model.isRunning ? raised : DL.good,
                                                ink: model.isRunning ? ink : .black))

                if let url = model.logFileURL {
                    ShareLink(item: url) {
                        Label("LOG", systemImage: "square.and.arrow.up")
                            .font(.system(size: 15, weight: .bold, design: .rounded))
                            .padding(.horizontal, 20)
                    }
                    .buttonStyle(CapsuleButtonStyle(fill: raised, ink: ink))
                }
            }
            HStack {
                Text("samples: \(model.gpsSampleCount)")
                Spacer()
                // S2 workout lab (FRO-395) — kept out of the S1 measurement
                // surface; low-lit so it doesn't skew the lit-pixel budget.
                Button("LAB") { showLab = true }
            }
            .font(.caption2.monospaced())
            .foregroundStyle(inkTertiary)
        }
        .fullScreenCover(isPresented: $showLab) {
            WorkoutLabScreen(controller: workout)
        }
    }

    /// The fractional digits are load-bearing, not decoration: everything else
    /// on screen only changes at GPS rate, so without per-tick content each
    /// refresh arm would diff an identical tree and never actually drive the
    /// panel at its cadence — the A/B would measure wasted CPU, not refresh
    /// cost. Tenths repaint the 10 Hz arm every tick; hundredths the 60 Hz arm.
    private func elapsedText(now: Date) -> String {
        guard let start = model.startDate, model.isRunning else { return "--:--" }
        let interval = now.timeIntervalSince(start)
        let seconds = Int(interval)
        let base = String(format: "%d:%02d:%02d", seconds / 3600, (seconds % 3600) / 60, seconds % 60)
        return switch model.refreshMode {
        case .low: base + String(format: ".%d", Int(interval * 10) % 10)
        case .high: base + String(format: ".%02d", Int(interval * 100) % 100)
        }
    }
}

/// Rule 8 of the design language: controls give pressed feedback (the
/// LoveFrom lesson) — the fill dims while the finger is down.
private struct CapsuleButtonStyle: ButtonStyle {
    let fill: Color
    let ink: Color

    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .foregroundStyle(ink)
            .frame(minHeight: 56)
            .background(fill.opacity(configuration.isPressed ? 0.7 : 1), in: .capsule)
    }
}

